DAYS = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"]
def grid(days):
    g = np.zeros((7, 24))
    for i, d in enumerate(days):
        for k, v in enumerate(d[1:]): g[i, d[0] + k] = v
    return g

rating = {"Hudson Square":4.4,"Bond Street":4.0,"Orchard Street":3.6,"SoHo":3.5,"Printing House":3.6,
          "Wall Street":3.6,"Tribeca":3.4,"Brookfield Place":3.8,"Greenwich Avenue":3.3}
year = {"Hudson Square":2025,"Bond Street":2016,"Orchard Street":2018,"SoHo":2006,"Printing House":2011,
        "Wall Street":2000,"Tribeca":2003,"Brookfield Place":2015,"Greenwich Avenue":2004}
out = {}
for club, days in data.items():
    g = grid(days); wk = g[1:5]  # Mon-Thu
    wkavg = wk.mean(0)
    open_hrs = g > 0
    total_wk = g[1:6].sum()
    ev = g[1:6, 17:22].sum() / total_wk            # weekday 5pm-10pm share
    morn = g[1:6, 5:9].sum() / total_wk            # weekday 5am-9am share
    mid = g[1:6, 9:17].sum() / total_wk            # weekday 9am-5pm share
    late = g[1:6, 20:24].sum() / total_wk          # weekday 8pm+ share
    load = g[open_hrs].mean()                      # avg busyness while open (relative to own peak)
    pk = np.unravel_index(g.argmax(), g.shape)
    wk_open = [hh for hh in range(6, 22) if wk[:, hh].min() > 0]
    quiet = min(wk_open, key=lambda hh: wkavg[hh])
    out[club] = {"evening_share": ev, "morning_share": morn, "midday_share": mid, "late_share": late,
                 "avg_load": load, "peak": f"{DAYS[pk[0]]} {pk[1]}:00", "quietest_weekday_hour": quiet,
                 "wk_6_8pm": float(wk[:, 18:20].mean()), "weekday_profile": wkavg.round(0).tolist()}
names = list(out)
for k in ["evening_share","morning_share","midday_share","avg_load"]:
    x = np.array([out[n][k] for n in names]); y = np.array([rating[n] for n in names])
    r = stats.linregress(x, y); print(f"rating ~ {k}: slope {r.slope:.2f} R2 {r.rvalue**2:.2f} p {r.pvalue:.3f}")
for n in sorted(names, key=lambda n: -out[n]["midday_share"]):
    o = out[n]; print(f"{n:17s} morn {o['morning_share']:.2f} mid {o['midday_share']:.2f} eve {o['evening_share']:.2f} late {o['late_share']:.2f} load {o['avg_load']:.0f} peak {o['peak']} quiet {o['quietest_weekday_hour']} 6-8pm {o['wk_6_8pm']:.0f}")
json.dump(out, open("popular_times.json", "w"), indent=1, default=float)
